#!/usr/bin/env bash
set -u
echo "== 解包全站公告 =="
mkdir -p /tmp/xm-notice && rm -rf /tmp/xm-notice/site && mkdir -p /tmp/xm-notice/site
echo '' | base64 -d > /tmp/xm-notice/u.tgz
tar -xzf /tmp/xm-notice/u.tgz -C /tmp/xm-notice/site
echo "== 覆盖到站点 =="
sudo cp -r /tmp/xm-notice/site/. /var/www/xinmo-site/
echo "== 校验 =="
grep -c 'site-notice.js' /var/www/xinmo-site/index.html
ls -l /var/www/xinmo-site/assets/js/site-notice.js /var/www/xinmo-site/assets/css/site-notice.css
echo "== DONE =="
